/* Stammtisch+ – private, installierbare Web-App (ohne Build-Tools) */
const DATA_KEY = 'stammtischplus.data.v1';
const CLOUD_KEY = 'stammtischplus.cloud.v1';
const BASELINE_KEY = 'stammtischplus.cloud.baseline.v1';
const DEFAULT = () => ({version:1,modifiedAt:new Date().toISOString(),members:[],meetings:[],fines:[],payments:[]});
const $ = s => document.querySelector(s);
const uid = () => crypto.randomUUID ? crypto.randomUUID() : `${Date.now()}-${Math.random().toString(36).slice(2)}`;
const esc = x => String(x ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const n = x => Math.max(0,Number.isFinite(+x)?Math.round(+x):0);
const money = cents => new Intl.NumberFormat('de-AT',{style:'currency',currency:'EUR'}).format((cents||0)/100);
const moneyToCents = text => {const value=String(text||'').trim().replace(/\s/g,'').replace(/€/g,'').replace(',','.');const f=Number(value);return Number.isFinite(f)&&f>=0?Math.round(f*100):NaN;};
const localDate = d => {const v=d||new Date(); const dt=typeof v==='string'?new Date(v+'T12:00:00'):v;return `${dt.getFullYear()}-${String(dt.getMonth()+1).padStart(2,'0')}-${String(dt.getDate()).padStart(2,'0')}`};
const today = ()=>localDate(new Date());
const fmtDate = d => d?new Date(d+'T12:00:00').toLocaleDateString('de-AT',{day:'2-digit',month:'long',year:'numeric'}):'–';
const yearOf = d => String(d||'').slice(0,4);
const initials = name=>String(name).trim().split(/\s+/).map(p=>p[0]||'').slice(0,2).join('').toUpperCase();
const byName = (a,b)=>a.name.localeCompare(b.name,'de');
const memberNo = m => {const raw=m?.memberNumber;if(raw===null||raw===undefined||raw==='')return null;const v=Number(raw);return Number.isSafeInteger(v)&&v>0?v:null;};
const byMemberNo = (a,b)=>(memberNo(a)??Number.MAX_SAFE_INTEGER)-(memberNo(b)??Number.MAX_SAFE_INTEGER)||byName(a,b);
function rotationMembers(){return data.members.filter(m=>m.active!==false&&memberNo(m)!==null).sort(byMemberNo);}
function suggestedOrganizer(date,excludeId=''){const candidates=rotationMembers();if(!candidates.length)return null;const last=[...data.meetings].filter(m=>m.id!==excludeId&&m.date<=date&&m.organizerId&&memberNo(member(m.organizerId))!==null).sort((a,b)=>b.date.localeCompare(a.date)||String(b.createdAt||'').localeCompare(String(a.createdAt||'')))[0];const previousNo=memberNo(member(last?.organizerId));return candidates.find(m=>previousNo!==null&&memberNo(m)>previousNo)||candidates[0];}
function yearCount(id,year){return stats(id,year).present+(String(year)==='2026'?n(member(id)?.historical2026Count):0);}

const assertData = v => {if(!v||typeof v!=='object'||!Array.isArray(v.members)||!Array.isArray(v.meetings)||!Array.isArray(v.fines)||!Array.isArray(v.payments))throw Error('Ungültiges Datenformat.');return v;};
function loadData(){try{const raw=localStorage.getItem(DATA_KEY);return raw?assertData(JSON.parse(raw)):DEFAULT();}catch(err){alert('Gespeicherte Daten konnten nicht geladen werden. Bitte keine neuen Daten speichern, bevor eine Sicherung geprüft wurde.');return DEFAULT();}}
let data=loadData(), page='home', rankYear=String(new Date().getFullYear()), cloudClient=null, cloudUser=null, cloudBusy=false, syncTimer=null, syncMessage='Nur auf diesem iPhone', cloudStatus='local';
function persist(){data.modifiedAt=new Date().toISOString();try{localStorage.setItem(DATA_KEY,JSON.stringify(data));}catch(e){alert('Speichern fehlgeschlagen. Bitte exportiere deine Daten als JSON und prüfe den Gerätespeicher.');throw e;}render();queueSync();}
function doneMeeting(m){return m.finalized===true && m.date<=today();}
function member(id){return data.members.find(x=>x.id===id);}
function finePaid(id){return data.payments.filter(p=>p.fineId===id).reduce((s,p)=>s+n(p.amountCents),0);}
function fineOpen(f){return Math.max(0,n(f.amountCents)-finePaid(f.id));}
function stats(id,year){const meetings=data.meetings.filter(m=>doneMeeting(m)&&(!year||yearOf(m.date)===String(year)));const present=meetings.filter(m=>m.attendance?.[id]?.status==='present').length;const eligible=meetings.filter(m=>Object.hasOwn(m.attendance||{},id)).length;return {present,eligible,pct:eligible?Math.round(100*present/eligible):0};}
function allTime(id){return n(member(id)?.historicalCount)+stats(id).present;}
function rankRows(year){return [...data.members].sort((a,b)=>(year?yearCount(b.id,year)-yearCount(a.id,year):allTime(b.id)-allTime(a.id))||a.name.localeCompare(b.name,'de')).map((m,i)=>({...m,place:i+1,count:year?yearCount(m.id,year):allTime(m.id),pct:stats(m.id,year).pct}));}
function icon(k){const paths={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-6v-7h-4v7H4a1 1 0 0 1-1-1z"/>',meetings:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 10h18M8 15l2 2 5-5"/>',members:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8zM22 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/>',ranking:'<path d="M8 21h8M12 17v4M7 4h10v7a5 5 0 0 1-10 0V4ZM7 6H3v2a4 4 0 0 0 4 4M17 6h4v2a4 4 0 0 1-4 4"/>',fines:'<rect x="3" y="5" width="18" height="15" rx="2"/><path d="M3 9h18M16 15h2M7 3v2"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.7 1.7 0 0 0 .3 1.9l.1.1-2.3 2.3-.1-.1a1.7 1.7 0 0 0-1.9-.3 1.7 1.7 0 0 0-1 1.6v.2h-3.2v-.2a1.7 1.7 0 0 0-1-1.6 1.7 1.7 0 0 0-1.9.3l-.1.1-2.3-2.3.1-.1a1.7 1.7 0 0 0 .3-1.9 1.7 1.7 0 0 0-1.6-1H4v-3.2h.2a1.7 1.7 0 0 0 1.6-1 1.7 1.7 0 0 0-.3-1.9l-.1-.1 2.3-2.3.1.1a1.7 1.7 0 0 0 1.9.3 1.7 1.7 0 0 0 1-1.6V4h3.2v.2a1.7 1.7 0 0 0 1 1.6 1.7 1.7 0 0 0 1.9-.3l.1-.1 2.3 2.3-.1.1a1.7 1.7 0 0 0-.3 1.9 1.7 1.7 0 0 0 1.6 1h.2v3.2h-.2a1.7 1.7 0 0 0-1.6 1z"/>',cloud:'<path d="M20 16.6a4 4 0 0 0-2-7.5A6 6 0 0 0 6.4 10 4 4 0 0 0 7 18h11"/><path d="m10 15 2 2 4-4"/>'};return `<svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${paths[k]||paths.home}</svg>`;}
const navItems=[['home','Start'],['meetings','Treffen'],['members','Mitglieder'],['ranking','Rangliste'],['fines','Kassa'],['settings','Mehr']];
function render(){document.querySelector('#nav').innerHTML=navItems.map(([key,label])=>`<button class="navbutton ${page===key?'active':''}" type="button" data-page="${key}" aria-label="${label}">${icon(key)}<span>${label}</span></button>`).join('');const renderers={home:homeHTML,meetings:meetingsHTML,members:membersHTML,ranking:rankingHTML,fines:finesHTML,settings:settingsHTML};$('#app').innerHTML=`<div class="top"><div class="brand"><div class="logo">S+</div><div><strong>Stammtisch+</strong><small>Dein digitales Stammtischbuch</small></div></div><button class="ghost tiny" data-page="settings" type="button"><span class="status ${cloudStatus==='connected'?'good':''}"></span>${cloudStatus==='connected'?'Cloud aktiv':'Lokal'}</button></div>${renderers[page]()}`;}
function pageHead(eyebrow,title,description){return `<div class="eyebrow">${eyebrow}</div><h1 class="title">${title}</h1>${description?`<p class="subtitle">${description}</p>`:''}`;}
function empty(emoji,text,sub=''){return `<div class="empty"><div class="emoji">${emoji}</div><strong>${text}</strong>${sub?`<p class="hint">${sub}</p>`:''}</div>`;}
function homeHTML(){const completed=data.meetings.filter(doneMeeting).sort((a,b)=>b.date.localeCompare(a.date));const latest=completed.slice(0,4);const participants=completed.reduce((sum,m)=>sum+Object.values(m.attendance||{}).filter(a=>a.status==='present').length,0);const finesTotal=data.fines.reduce((s,f)=>s+n(f.amountCents),0);const paid=data.payments.reduce((s,p)=>s+n(p.amountCents),0);const thisYear=data.meetings.filter(m=>doneMeeting(m)&&yearOf(m.date)===yearOf(today()));return `${pageHead('Deine Übersicht','Servus beim Stammtisch!','Alles Wichtige auf einen Blick – Anwesenheit, Platzierungen und Strafenkassa.')}<div class="metric-grid"><div class="metric"><small>Aktive Mitglieder</small><div class="value">${data.members.filter(m=>m.active!==false).length}</div></div><div class="metric"><small>Abgeschlossene Treffen</small><div class="value">${completed.length}</div></div><div class="metric"><small>Teilnahmen insgesamt*</small><div class="value green">${participants}</div></div><div class="metric"><small>Strafen offen</small><div class="value red">${money(finesTotal-paid)}</div></div></div><p class="hint">* Neu in dieser App dokumentierte Teilnahmen ohne historische Startwerte.</p><div class="notice" style="margin-top:12px">Nächster Organisator laut Mitgliedsnummer: <strong>${(()=>{const p=suggestedOrganizer(today());return p?`Nr. ${memberNo(p)} · ${esc(p.name)}`:'Noch nicht bestimmbar'})()}</strong></div><div class="toolbar"><button class="button" data-action="meeting-new">+ Stammtisch erfassen</button><button class="ghost" data-action="member-new">+ Mitglied</button></div><div class="cols-main"><section class="card"><h2>Letzte Stammtische</h2>${latest.length?`<div class="list">${latest.map(m=>`<div class="item"><div class="avatar">${String(new Date(m.date+'T12:00:00').getDate()).padStart(2,'0')}</div><div class="details"><strong>${fmtDate(m.date)}</strong><small>${esc(m.location||'Ohne Lokal')} · ${Object.values(m.attendance||{}).filter(a=>a.status==='present').length} anwesend</small></div><button class="smallbtn" data-action="meeting-edit" data-id="${m.id}">Öffnen</button></div>`).join('')}</div>`:empty('📅','Noch keine Stammtische','Erfasse deinen ersten Stammtisch und markiere die Teilnehmer.')}<div class="separator"></div><span class="hint">${thisYear.length} abgeschlossene Treffen im Jahr ${yearOf(today())}</span></section><section class="card"><h2>Top 3 · Ewige Rangliste</h2>${data.members.length?`<div class="list">${rankRows(null).slice(0,3).map((m,i)=>`<div class="item"><span style="font-size:22px">${['🥇','🥈','🥉'][i]}</span><div class="details"><strong>${esc(m.name)}</strong><small>${n(m.historicalCount)} historische + ${stats(m.id).present} neue Teilnahmen</small></div><strong class="number">${m.count}</strong></div>`).join('')}</div>`:empty('🏆','Noch keine Platzierungen','Historische Teilnahmen in den Mitgliedern eintragen.')}<div class="separator"></div><button class="ghost" data-page="ranking">Alle Ranglisten ansehen →</button></section></div>`;}
function membersHTML(){const members=[...data.members].sort(byMemberNo);return `${pageHead('Organisation','Mitglieder','Verwalte Mitgliedsnummern und die historischen Teilnahme-Startwerte.')}<div class="toolbar"><button class="button" data-action="member-new">+ Mitglied hinzufügen</button><button class="ghost" data-action="bulk-2026">2026-Startwerte erfassen</button><span class="muted tiny">${data.members.length} Mitglieder</span></div><div class="card">${members.length?`<div class="list">${members.map(m=>`<div class="item"><div class="avatar">${memberNo(m)===null?esc(initials(m.name)):memberNo(m)}</div><div class="details"><strong>${memberNo(m)===null?'':`Nr. ${memberNo(m)} · `}${esc(m.name)} ${m.active===false?'<span class="chip gray">Archiviert</span>':''}</strong><small>2026: ${yearCount(m.id,'2026')} (${n(m.historical2026Count)} Startwert + ${stats(m.id,'2026').present} erfasst) · ewig: ${allTime(m.id)}</small></div><button class="smallbtn" data-action="member-edit" data-id="${m.id}">Bearbeiten</button></div>`).join('')}</div>`:empty('👥','Hier ist noch niemand','Lege Mitglieder mit Nummer und ihren bisherigen Teilnahmen an.')}</div><div class="notice">Der einmalige 2026-Startwert zählt <strong>nur zusätzlich für die Jahresrangliste 2026</strong>. Für die ewige Rangliste gilt weiter: Gesamt-Startwert + neue Treffen. Die bisherigen 2026-Teilnahmen müssen daher bereits im Gesamt-Startwert enthalten sein.</div>`;}
function meetingsHTML(){const meetings=[...data.meetings].sort((a,b)=>b.date.localeCompare(a.date));const next=suggestedOrganizer(today());return `${pageHead('Anwesenheitsbuch','Stammtische','Wer war da? Wer fehlte – und warum? Abwesenheitsstrafen bleiben optional.')}<div class="toolbar"><button class="button" data-action="meeting-new">+ Neues Treffen</button><span class="hint">Nur abgeschlossene Treffen bis heute zählen in den Ranglisten.</span></div><div class="notice">Vorschlag für den nächsten Organisator: <strong>${next?`Nr. ${memberNo(next)} · ${esc(next.name)}`:'Bitte zuerst Mitgliedsnummern für aktive Mitglieder eintragen'}</strong>. Beim neuen Treffen wird der Organisator automatisch vorbelegt und kann geändert werden.</div><div class="card">${meetings.length?`<div class="list">${meetings.map(m=>{const a=Object.values(m.attendance||{});const organizer=member(m.organizerId);return `<div class="item"><div class="avatar">${esc(String(new Date(m.date+'T12:00:00').getDate()).padStart(2,'0'))}</div><div class="details"><strong>${fmtDate(m.date)}</strong><small>${esc(m.location||'Kein Lokal')} · Organisator: ${organizer?`${memberNo(organizer)!==null?'Nr. '+memberNo(organizer)+' · ':''}${esc(organizer.name)}`:'Nicht festgelegt'}<br>${a.filter(x=>x.status==='present').length} da · ${a.filter(x=>x.status==='absent').length} fehlend</small></div><span class="chip ${doneMeeting(m)?'':'gray'}">${doneMeeting(m)?'Abgeschlossen':'Entwurf'}</span><button class="smallbtn" data-action="meeting-edit" data-id="${m.id}">Öffnen</button></div>`}).join('')}</div>`:empty('📅','Keine Treffen vorhanden','Lege einen Stammtisch an und wähle die Anwesenden aus.')}</div>`;}
function rankingHTML(){const years=[...new Set(['2026',yearOf(today()),...data.meetings.map(m=>yearOf(m.date))])].filter(Boolean).sort().reverse();const isAll=rankYear==='all';const rows=rankRows(isAll?null:rankYear);return `${pageHead('Nur Anwesenheit zählt','Ranglisten','Keine Strafe und kein Abwesenheitsgrund beeinflussen die Platzierung.')}<div class="card"><div class="toolbar" style="margin:0 0 14px"><div class="pill-group"><button class="pill ${isAll?'selected':''}" data-action="rank-year" data-year="all">Ewige Rangliste</button>${years.map(y=>`<button class="pill ${rankYear===y?'selected':''}" data-action="rank-year" data-year="${y}">${y}</button>`).join('')}</div></div><div class="notice">${isAll?'Ewige Rangliste = historischer Gesamt-Startwert + alle neu erfassten Teilnahmen.':rankYear==='2026'?'2026 = einmaliger Teilnahme-Startwert bis zur Einführung der App + 2026 danach erfasste Teilnahmen.':'Jahresrangliste = Anwesenheiten bei abgeschlossenen Treffen in '+esc(rankYear)+'.'}</div><div class="separator"></div>${rows.length?`<div class="tablewrap"><table class="table"><thead><tr><th>Platz</th><th>Mitglied</th><th>Teilnahmen</th></tr></thead><tbody>${rows.map((m,i)=>`<tr><td><strong>${i<3?['🥇','🥈','🥉'][i]:i+1+'.'}</strong></td><td>${memberNo(m)!==null?`<span class="muted">Nr. ${memberNo(m)}</span> · `:''}${esc(m.name)}${m.active===false?' <span class="chip gray">Archiv</span>':''}</td><td><strong>${m.count}</strong></td></tr>`).join('')}</tbody></table></div>`:empty('🏆','Noch keine Mitglieder')}<p class="hint">Bei Gleichstand entscheidet nur für die Reihenfolge der Name; die Teilnahmezahl bleibt gleich.</p></div>`;}
function finesHTML(){const fines=[...data.fines].sort((a,b)=>b.date.localeCompare(a.date));const total=fines.reduce((s,f)=>s+n(f.amountCents),0);const paid=data.payments.reduce((s,p)=>s+n(p.amountCents),0);return `${pageHead('Strafen & Zahlungen','Stammtischkassa','Strafen werden manuell vergeben. Teilzahlungen sind möglich und bleiben nachvollziehbar.')}<div class="metric-grid"><div class="metric"><small>Verhängte Strafen</small><div class="value">${money(total)}</div></div><div class="metric"><small>Eingesammelt</small><div class="value green">${money(paid)}</div></div><div class="metric"><small>Offen</small><div class="value red">${money(total-paid)}</div></div><div class="metric"><small>Straf-Einträge</small><div class="value">${fines.length}</div></div></div><div class="toolbar"><button class="button" data-action="fine-new">+ Strafe eintragen</button><button class="ghost" data-action="export-csv" data-kind="fines">CSV exportieren</button></div><div class="card"><h2>Strafen pro Mitglied</h2>${data.members.length?`<div class="list">${[...data.members].sort((a,b)=>{const aa=data.fines.filter(f=>f.memberId===a.id).reduce((s,f)=>s+fineOpen(f),0),bb=data.fines.filter(f=>f.memberId===b.id).reduce((s,f)=>s+fineOpen(f),0);return bb-aa||byName(a,b)}).map(m=>{const mf=fines.filter(f=>f.memberId===m.id);const open=mf.reduce((s,f)=>s+fineOpen(f),0);return `<div class="item"><div class="avatar">${esc(initials(m.name))}</div><div class="details"><strong>${esc(m.name)}</strong><small>${mf.length} Strafen · ${money(mf.reduce((s,f)=>s+n(f.amountCents)-fineOpen(f),0))} bezahlt</small></div><span class="number ${open?'':'muted'}">${money(open)}</span></div>`}).join('')}</div>`:empty('💶','Noch keine Mitglieder')}</div><div class="card"><h2>Einzelne Strafen</h2>${fines.length?`<div class="list">${fines.map(f=>{const open=fineOpen(f);return `<div class="item"><div class="details"><strong>${esc(member(f.memberId)?.name||'(gelöschtes Mitglied)')}</strong><small>${fmtDate(f.date)} · ${esc(f.reason)}<br>Gesamt ${money(f.amountCents)}, bezahlt ${money(n(f.amountCents)-open)}</small></div><div class="right"><span class="chip ${open?'red':''}">${open?money(open)+' offen':'Bezahlt'}</span><div style="margin-top:6px">${open?`<button class="smallbtn" data-action="fine-pay" data-id="${f.id}">Kassieren</button>`:''} <button class="smallbtn" data-action="fine-view" data-id="${f.id}">Details</button></div></div></div>`}).join('')}</div>`:empty('🧾','Noch keine Strafen','Du kannst Strafen hier oder direkt beim Eintragen einer Abwesenheit vergeben.')}</div>`;}
function settingsHTML(){const cfg=getCloudConfig();const sync=cloudStatus==='connected'?`<span class="chip">Verbunden</span>`:cloudStatus==='error'?`<span class="chip red">Verbindungsfehler</span>`:`<span class="chip gray">Noch nicht verbunden</span>`;return `${pageHead('Sicherung & Export','Mehr','Exportiere deine Daten und richte optional die geräteübergreifende Cloud ein.')}<section class="card"><div class="row"><h2>Cloud-Synchronisierung</h2>${sync}</div><p class="hint">${esc(syncMessage)}. Deine Daten sind ohne Cloud zunächst nur in diesem Browser gespeichert. Cloud benötigt ein Supabase-Projekt und die SQL-Einrichtung laut Anleitung.</p><div class="stack"><button class="button" data-action="cloud-setup">${cfg?'Cloud-Zugang verwalten':'Cloud einrichten'}</button>${cloudUser?`<button class="ghost" data-action="cloud-check">Jetzt synchronisieren</button>`:''}</div></section><section class="card"><h2>Excel / CSV-Export</h2><p class="hint">Die CSV-Dateien sind für Excel im deutschsprachigen Raum vorbereitet (Semikolon, UTF-8). Auf dem iPhone findest du Downloads in der Dateien-App.</p><div class="stack">${[['attendance','Anwesenheiten'],['ranking','Ranglisten inkl. 2026'],['fines','Strafen'],['payments','Zahlungen'],['members','Mitglieder inkl. Nummern']].map(([kind,label])=>`<button class="ghost" data-action="export-csv" data-kind="${kind}">↓ ${label} als CSV</button>`).join('')}</div></section><section class="card"><h2>Sicherung & Wiederherstellung</h2><p class="hint">Ein JSON-Backup enthält auch alle Abwesenheitsgründe, Notizen und Zahlungen. Bewahre es geschützt auf.</p><div class="stack"><button class="ghost" data-action="export-json">↓ Komplette Datensicherung (JSON)</button><label class="ghost" style="text-align:center;cursor:pointer;margin:0">↑ JSON-Backup importieren<input id="backupFile" type="file" accept="application/json,.json" style="display:none"></label></div></section><div class="notice warning"><strong>Privatsphäre:</strong> Fehlgründe können sensible persönliche Angaben enthalten. Nutze möglichst neutrale Formulierungen und exportiere Dateien nur an vertrauenswürdige Orte.</div>`;}
function modal(title,html){$('#dialog').innerHTML=`<div class="modalbody"><div class="modalhead"><h2>${title}</h2><button type="button" class="close" data-action="close" aria-label="Schließen">×</button></div>${html}</div>`;$('#dialog').showModal();}
const footer = (label='Speichern')=>`<div class="foot"><button type="button" class="ghost" data-action="close">Abbrechen</button><button class="button" type="submit">${label}</button></div>`;
function memberForm(id){const m=member(id)||{id:'',name:'',memberNumber:null,historicalCount:0,historical2026Count:0,active:true};const nextNo=(()=>{let x=1;const used=new Set(data.members.map(memberNo).filter(Boolean));while(used.has(x))x++;return x})();modal(id?'Mitglied bearbeiten':'Neues Mitglied',`<form data-form="member"><input type="hidden" name="id" value="${esc(m.id)}"><div class="field"><label for="mname">Name</label><input id="mname" name="name" value="${esc(m.name)}" maxlength="100" autocomplete="off" required></div><div class="field"><label for="mnumber">Mitgliedsnummer</label><input id="mnumber" name="memberNumber" type="number" min="1" step="1" value="${memberNo(m)??(id?'':nextNo)}" placeholder="z. B. 12"><p class="hint">Eindeutige Nummer. Die Organisator-Reihenfolge läuft aufsteigend nach diesen Nummern.</p></div><div class="field"><label for="hcount">Historischer Startwert: Teilnahmen insgesamt</label><input id="hcount" name="historicalCount" type="number" min="0" step="1" value="${n(m.historicalCount)}" required><p class="hint">Alle Teilnahmen vor Beginn der digitalen Erfassung, einschließlich der bisherigen Teilnahmen im Jahr 2026. Zählt für die ewige Rangliste.</p></div><div class="field"><label for="ycount">Historischer Startwert: Teilnahmen 2026</label><input id="ycount" name="historical2026Count" type="number" min="0" step="1" value="${n(m.historical2026Count)}" required><p class="hint">Nur Teilnahmen von 2026, die du noch NICHT als Einzeltermine in dieser App erfasst hast. Wird zur Jahresrangliste 2026 hinzugerechnet, aber NICHT nochmals zur ewigen Rangliste.</p></div><div class="field"><label style="display:flex;align-items:center;gap:9px"><input type="checkbox" name="active" ${m.active!==false?'checked':''}>Aktives Mitglied</label></div>${footer()}</form>`);}
function bulk2026Form(){const sorted=[...data.members].sort(byMemberNo);if(!sorted.length)return alert('Bitte zuerst Mitglieder anlegen.');modal('2026-Startwerte einmalig erfassen',`<p class="hint">Trage die Teilnahmen im Jahr 2026 vor Beginn der digitalen Erfassung ein. Nicht die hier erfassten Treffen mitzählen. Der Gesamt-Startwert für die ewige Rangliste muss diese Teilnahmen bereits enthalten.</p><form data-form="bulk-2026">${sorted.map(m=>`<div class="row field"><label style="flex:1;margin:0" for="baseline-${m.id}">${memberNo(m)!==null?'Nr. '+memberNo(m)+' · ':''}${esc(m.name)}<div class="hint">Gesamt-Startwert: ${n(m.historicalCount)}</div></label><input id="baseline-${m.id}" name="baseline-${m.id}" type="number" min="0" step="1" value="${n(m.historical2026Count)}" required style="max-width:115px" aria-label="2026-Teilnahmen ${esc(m.name)}"></div>`).join('')}${footer('2026-Startwerte speichern')}</form>`);}
function saveBulk2026(fd){const updates=[];for(const m of data.members){const x=Number(fd.get(`baseline-${m.id}`));if(!Number.isSafeInteger(x)||x<0)return alert(`Ungültiger 2026-Startwert für ${m.name}.`);if(x>n(m.historicalCount))return alert(`Der 2026-Startwert von ${m.name} darf nicht größer als der Gesamt-Startwert (${n(m.historicalCount)}) sein. Bitte zuerst das Mitglied bearbeiten.`);updates.push([m,x]);}for(const [m,x] of updates)m.historical2026Count=x;closeModal();persist();}
const reasonOptions=['Krankheit','Urlaub','Beruflich verhindert','Privater Termin','Unentschuldigt','Sonstiger Grund'];
function absenceFields(id,entry,linkedFine){const present=entry?.status==='absent';return `<div class="absence-extra ${present?'':'hidden'}" data-absence-for="${id}"><div class="field"><label>Abwesenheitsgrund</label><input name="reason-${id}" list="reasons-${id}" value="${esc(entry?.reason||'')}" maxlength="150" placeholder="Grund auswählen oder frei eingeben"><datalist id="reasons-${id}">${reasonOptions.map(o=>`<option value="${esc(o)}">`).join('')}</datalist></div><div class="field"><label>Bemerkung (optional)</label><input name="note-${id}" value="${esc(entry?.note||'')}" maxlength="300" placeholder="Optionale Notiz"></div><div class="field"><label>Strafe in € (optional)</label><input name="fine-${id}" inputmode="decimal" type="text" value="${linkedFine?esc((linkedFine.amountCents/100).toFixed(2).replace('.',',')):''}" placeholder="z. B. 5,00"><p class="hint">Leer lassen = keine neue Strafe.${linkedFine?' Vorhandene Strafe wird aktualisiert, sofern keine Zahlungen vorliegen.':''}</p></div></div>`;}
function meetingForm(id){const m=data.meetings.find(x=>x.id===id)||{id:'',date:today(),location:'',notes:'',finalized:false,attendance:{},organizerId:null};const attendanceMembers=[...data.members].filter(person=>person.active!==false||Object.hasOwn(m.attendance||{},person.id)).sort(byMemberNo);const organizerMembers=[...data.members].filter(person=>person.active!==false||person.id===m.organizerId).sort(byMemberNo);const proposed=m.organizerId||(suggestedOrganizer(m.date,m.id)?.id||'');modal(id?'Stammtisch bearbeiten':'Neuer Stammtisch',`<form data-form="meeting"><input type="hidden" name="id" value="${esc(m.id)}"><div class="cols"><div class="field"><label>Datum</label><input type="date" name="date" value="${esc(m.date)}" required></div><div class="field"><label>Lokal</label><input name="location" maxlength="120" value="${esc(m.location)}" placeholder="Gasthaus …"></div></div><div class="field"><label>Organisator dieses Stammtischs</label><select name="organizerId" data-organizer-auto="${id?'off':'on'}"><option value="">Nicht festgelegt</option>${organizerMembers.map(person=>`<option value="${person.id}" ${proposed===person.id?'selected':''}>${memberNo(person)!==null?'Nr. '+memberNo(person)+' · ':''}${esc(person.name)}</option>`).join('')}</select><p class="hint">Voreinstellung: nächsthöhere aktive Mitgliedsnummer nach dem letzten eingetragenen Organisator. Nach der höchsten Nummer geht es mit der niedrigsten weiter. Du kannst die Person ändern.</p></div><div class="field"><label>Notizen (optional)</label><textarea name="notes" maxlength="1000" placeholder="Besondere Ereignisse">${esc(m.notes||'')}</textarea></div><h3>Anwesenheit</h3><p class="hint">Tippe auf „Da“ oder „Fehlt“. Bei „Fehlt“ muss für den Abschluss ein Grund ausgewählt werden.</p>${attendanceMembers.length?attendanceMembers.map(person=>{const entry=m.attendance?.[person.id]||{};const linkedFine=data.fines.find(f=>f.meetingId===m.id&&f.memberId===person.id&&f.source==='absence');return `<div class="member-att"><div class="row"><strong>${memberNo(person)!==null?'Nr. '+memberNo(person)+' · ':''}${esc(person.name)}</strong><div class="seg"><button type="button" class="${entry.status==='present'?'on yes':''}" data-action="attend" data-id="${person.id}" data-status="present">✓ Da</button><button type="button" class="${entry.status==='absent'?'on no':''}" data-action="attend" data-id="${person.id}" data-status="absent">× Fehlt</button></div></div><input type="hidden" name="status-${person.id}" value="${esc(entry.status||'')}">${absenceFields(person.id,entry,linkedFine)}</div>`}).join(''):empty('👥','Noch keine Mitglieder','Bitte zuerst ein Mitglied anlegen.')}<div class="field"><label style="display:flex;align-items:center;gap:8px"><input type="checkbox" name="finalized" ${m.finalized?'checked':''}>Stammtisch abschließen und für Ranglisten zählen</label><p class="hint">Bei einem abgeschlossenen Treffen muss jedes aufgelistete Mitglied als anwesend oder abwesend markiert sein. Zukünftige Treffen zählen erst ab ihrem Datum.</p></div>${footer(id?'Änderungen speichern':'Stammtisch speichern')}${id?`<div class="separator"></div><button type="button" class="danger-btn" data-action="meeting-delete" data-id="${m.id}">Treffen löschen</button>`:''}</form>`);}
function fineForm(){if(!data.members.length)return alert('Bitte lege zuerst ein Mitglied an.');modal('Strafe eintragen',`<form data-form="fine"><div class="field"><label>Mitglied</label><select name="memberId" required>${[...data.members].sort(byName).map(m=>`<option value="${m.id}">${esc(m.name)}</option>`).join('')}</select></div><div class="cols"><div class="field"><label>Datum</label><input name="date" type="date" value="${today()}" required></div><div class="field"><label>Betrag (€)</label><input name="amount" type="text" inputmode="decimal" placeholder="5,00" required></div></div><div class="field"><label>Grund</label><input name="reason" maxlength="300" placeholder="z. B. Zu spät gekommen" required></div>${footer('Strafe erfassen')}</form>`);}
function payForm(id){const f=data.fines.find(x=>x.id===id);if(!f)return;const open=fineOpen(f);modal('Zahlung erfassen',`<div class="notice"><strong>${esc(member(f.memberId)?.name||'Mitglied')}</strong><br>${esc(f.reason)}<br>Noch offen: <strong>${money(open)}</strong></div><form data-form="payment"><input name="fineId" type="hidden" value="${f.id}"><div class="cols"><div class="field"><label>Betrag (€)</label><input name="amount" inputmode="decimal" type="text" value="${(open/100).toFixed(2).replace('.',',')}" required></div><div class="field"><label>Datum</label><input type="date" name="date" value="${today()}" required></div></div><div class="field"><label>Zahlungsart</label><select name="method"><option>Bar</option><option>Überweisung</option><option>Sonstiges</option></select></div><div class="field"><label>Notiz (optional)</label><input name="note" maxlength="200"></div>${footer('Zahlung buchen')}</form>`);}
function fineView(id){const f=data.fines.find(x=>x.id===id);if(!f)return;const payments=data.payments.filter(p=>p.fineId===id).sort((a,b)=>b.date.localeCompare(a.date));modal('Strafendetails',`<div class="stack"><div><label>Mitglied</label><strong>${esc(member(f.memberId)?.name||'Unbekannt')}</strong></div><div><label>Grund</label><strong>${esc(f.reason)}</strong></div><div><label>Verhängt am</label>${fmtDate(f.date)}</div><div class="row"><div><label>Gesamtbetrag</label><strong>${money(f.amountCents)}</strong></div><div class="right"><label>Noch offen</label><strong>${money(fineOpen(f))}</strong></div></div></div><div class="separator"></div><h3>Zahlungen</h3>${payments.length?payments.map(p=>`<div class="item"><div class="details"><strong>${money(p.amountCents)}</strong><small>${fmtDate(p.date)} · ${esc(p.method||'Bar')} ${p.note?`· ${esc(p.note)}`:''}</small></div><button class="smallbtn" data-action="payment-delete" data-id="${p.id}">Stornieren</button></div>`).join(''):empty('🧾','Noch keine Zahlung')}<div class="foot">${fineOpen(f)?`<button class="button" data-action="fine-pay" data-id="${f.id}">Zahlung erfassen</button>`:''}<button class="ghost" data-action="close">Schließen</button></div>${payments.length?'':'<div class="separator"></div><button class="danger-btn" data-action="fine-delete" data-id="'+f.id+'">Unbezahlte Strafe löschen</button>'}`);}
function attStatus(id,status){const root=$('#dialog');const field=root.querySelector(`[name="status-${id}"]`);if(!field)return;field.value=field.value===status?'':status;const parent=field.closest('.member-att');parent.querySelectorAll('[data-action="attend"]').forEach(b=>b.className=(field.value===b.dataset.status?`on ${b.dataset.status==='present'?'yes':'no'}`:''));parent.querySelector('.absence-extra').classList.toggle('hidden',field.value!=='absent');}
function saveMember(fd){const id=String(fd.get('id')||''),name=String(fd.get('name')||'').trim(),count=Number(fd.get('historicalCount')),count2026=Number(fd.get('historical2026Count')),rawNo=String(fd.get('memberNumber')||'').trim(),number=rawNo===''?null:Number(rawNo);if(!name||!Number.isSafeInteger(count)||count<0||!Number.isSafeInteger(count2026)||count2026<0)return alert('Bitte einen Namen und gültige ganze Teilnahmezahlen eingeben.');if(count2026>count)return alert('Die bisherigen Teilnahmen 2026 dürfen nicht höher sein als der historische Gesamt-Startwert. Beide Zahlen bitte prüfen.');if(number!==null&&(!Number.isSafeInteger(number)||number<=0))return alert('Die Mitgliedsnummer muss eine positive ganze Zahl sein.');if(data.members.some(m=>m.name.toLocaleLowerCase('de')===name.toLocaleLowerCase('de')&&m.id!==id))return alert('Dieser Mitgliedsname ist bereits vorhanden.');if(number!==null&&data.members.some(m=>memberNo(m)===number&&m.id!==id))return alert(`Mitgliedsnummer ${number} ist bereits vergeben.`);const previous=member(id)||{};const value={...previous,id:id||uid(),name,memberNumber:number,historicalCount:count,historical2026Count:count2026,active:fd.has('active')};if(id){data.members=data.members.map(m=>m.id===id?value:m)}else{data.members.push(value)}closeModal();persist();}
function saveMeeting(fd){const id=String(fd.get('id')||''),date=String(fd.get('date')||''),location=String(fd.get('location')||'').trim(),notes=String(fd.get('notes')||'').trim(),organizerId=String(fd.get('organizerId')||''),finalized=fd.has('finalized');if(!/^\d{4}-\d{2}-\d{2}$/.test(date))return alert('Bitte ein gültiges Datum auswählen.');if(organizerId&&!member(organizerId))return alert('Bitte einen gültigen Organisator auswählen.');const activeMembers=[...data.members].filter(m=>m.active!==false||Object.hasOwn((data.meetings.find(t=>t.id===id)||{}).attendance||{},m.id)).sort(byName);const attendance={},fineChanges=[];for(const m of activeMembers){const status=String(fd.get(`status-${m.id}`)||'');if(finalized&&!['present','absent'].includes(status))return alert(`Bitte Anwesenheit für ${m.name} markieren oder als Entwurf speichern.`);if(status==='present'){attendance[m.id]={status:'present'};}if(status==='absent'){const reason=String(fd.get(`reason-${m.id}`)||'').trim(),note=String(fd.get(`note-${m.id}`)||'').trim();if(finalized&&!reason)return alert(`Bitte Abwesenheitsgrund für ${m.name} eintragen.`);attendance[m.id]={status:'absent',reason,note};const rawFine=String(fd.get(`fine-${m.id}`)||'').trim();const amount=rawFine?moneyToCents(rawFine):0;if(!Number.isSafeInteger(amount)||amount<0)return alert(`Ungültiger Strafbetrag für ${m.name}.`);fineChanges.push({memberId:m.id,amount,reason});}}
 const mtId=id||uid();for(const item of fineChanges){const existing=data.fines.find(f=>f.meetingId===mtId&&f.memberId===item.memberId&&f.source==='absence');if(existing&&item.amount<finePaid(existing.id))return alert(`Die Strafe für ${member(item.memberId).name} darf nicht unter den bereits bezahlten Betrag ${money(finePaid(existing.id))} gesenkt werden.`);}
 const existing=data.meetings.find(m=>m.id===id);const newMeeting={id:mtId,date,location,notes,organizerId:organizerId||null,finalized,attendance,createdAt:existing?.createdAt||new Date().toISOString()};if(id)data.meetings=data.meetings.map(m=>m.id===id?newMeeting:m);else data.meetings.push(newMeeting);
 for(const item of fineChanges){const existingFine=data.fines.find(f=>f.meetingId===mtId&&f.memberId===item.memberId&&f.source==='absence');if(existingFine){if(item.amount>0){existingFine.amountCents=item.amount;existingFine.reason=`Abwesenheit: ${item.reason}`;existingFine.date=date;}else if(!finePaid(existingFine.id)){data.fines=data.fines.filter(f=>f.id!==existingFine.id);}}else if(item.amount>0){data.fines.push({id:uid(),memberId:item.memberId,meetingId:mtId,source:'absence',date,reason:`Abwesenheit: ${item.reason}`,amountCents:item.amount});}}
 closeModal();persist();}
function saveFine(fd){const amount=moneyToCents(fd.get('amount'));const memberId=String(fd.get('memberId')),reason=String(fd.get('reason')||'').trim(),date=String(fd.get('date')||'');if(!member(memberId)||!reason||!Number.isSafeInteger(amount)||amount<=0||!/^\d{4}-\d{2}-\d{2}$/.test(date))return alert('Bitte Mitglied, Grund, Datum und einen positiven Betrag eintragen.');data.fines.push({id:uid(),memberId,date,reason,amountCents:amount,meetingId:null,source:'manual'});closeModal();persist();}
function savePayment(fd){const fine=data.fines.find(f=>f.id===fd.get('fineId'));if(!fine)return;const amount=moneyToCents(fd.get('amount'));if(!Number.isSafeInteger(amount)||amount<=0||amount>fineOpen(fine))return alert(`Zahlung muss größer als 0 € und maximal ${money(fineOpen(fine))} sein.`);data.payments.push({id:uid(),fineId:fine.id,date:String(fd.get('date')),amountCents:amount,method:String(fd.get('method')||'Bar'),note:String(fd.get('note')||'').trim()});closeModal();persist();}
function closeModal(){if($('#dialog').open)$('#dialog').close();}
/* UTF-8 / Excel-friendly exports */
function csvCell(v){const s=String(v??'');return `"${s.replace(/"/g,'""')}"`;}
function makeCSV(headers,rows){return '\ufeff'+[headers,...rows].map(line=>line.map(csvCell).join(';')).join('\r\n')+'\r\n';}
function download(content,name,mime){const blob=new Blob([content],{type:mime});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),15000);}
function exportCSV(kind){let headers=[],rows=[];
 if(kind==='attendance'){headers=['Datum','Lokal','Organisator','Mitgliedsnummer','Mitglied','Anwesenheit','Abwesenheitsgrund','Notiz','Abgeschlossen'];rows=data.meetings.flatMap(m=>data.members.filter(person=>m.attendance?.[person.id]).map(person=>{const a=m.attendance[person.id];return [m.date,m.location,member(m.organizerId)?.name||'',memberNo(person)||'',person.name,a.status==='present'?'Anwesend':'Abwesend',a.reason||'',a.note||'',m.finalized?'Ja':'Nein']}));}
 else if(kind==='ranking'){headers=['Jahr','Platz','Mitgliedsnummer','Mitglied','Teilnahmen','Historischer Gesamt-Startwert','Startwert 2026','Neu erfasste Teilnahmen im Jahr','Neue Teilnahmen gesamt'];const years=[...new Set(['2026',...data.meetings.map(m=>yearOf(m.date))])].filter(Boolean).sort();rows=[...years.flatMap(year=>rankRows(year).map(m=>[year,m.place,memberNo(m)||'',m.name,m.count,n(m.historicalCount),n(m.historical2026Count),stats(m.id,year).present,stats(m.id).present])),...rankRows(null).map(m=>['Ewig',m.place,memberNo(m)||'',m.name,m.count,n(m.historicalCount),n(m.historical2026Count),stats(m.id).present,stats(m.id).present])];}
 else if(kind==='fines'){headers=['Datum','Mitglied','Grund','Verhängte Strafe EUR','Bezahlt EUR','Offen EUR','Treffen-Datum'];rows=data.fines.map(f=>[f.date,member(f.memberId)?.name||'',f.reason,(f.amountCents/100).toFixed(2).replace('.',','),(finePaid(f.id)/100).toFixed(2).replace('.',','),(fineOpen(f)/100).toFixed(2).replace('.',','),data.meetings.find(m=>m.id===f.meetingId)?.date||'']);}
 else if(kind==='payments'){headers=['Datum','Mitglied','Strafgrund','Betrag EUR','Zahlungsart','Notiz'];rows=data.payments.map(p=>{const f=data.fines.find(f=>f.id===p.fineId);return[p.date,member(f?.memberId)?.name||'',f?.reason||'',(p.amountCents/100).toFixed(2).replace('.',','),p.method,p.note]});}
 else if(kind==='members'){headers=['Mitgliedsnummer','Mitglied','Aktiv','Historischer Gesamt-Startwert','Historischer Startwert 2026','Neue Teilnahmen 2026','2026 gesamt','Neue Teilnahmen gesamt','Ewige Teilnahmen'];rows=data.members.map(m=>[memberNo(m)||'',m.name,m.active!==false?'Ja':'Nein',n(m.historicalCount),n(m.historical2026Count),stats(m.id,'2026').present,yearCount(m.id,'2026'),stats(m.id).present,allTime(m.id)]);}
 download(makeCSV(headers,rows),`Stammtisch_${kind}_${today()}.csv`,'text/csv;charset=utf-8');}
function exportJSON(){download(JSON.stringify(data,null,2),`Stammtisch_Backup_${today()}.json`,'application/json;charset=utf-8');}

/* Optionale persönliche Cloud: Supabase Auth + RLS-geschützter JSON-Datensatz */
const getCloudConfig=()=>{try{return JSON.parse(localStorage.getItem(CLOUD_KEY)||'null')}catch{return null}};
let pendingRemote=null;
async function initCloudClient(){const cfg=getCloudConfig();if(!cfg?.url||!cfg?.key)throw Error('Bitte zunächst Cloud-URL und Publishable Key eintragen.');if(!/^https:\/\/[a-z0-9-]+\.supabase\.co\/?$/i.test(cfg.url.trim()))throw Error('Ungültige Supabase-Projekt-URL.');const {createClient}=await import('https://esm.sh/@supabase/supabase-js@2');cloudClient=createClient(cfg.url.trim().replace(/\/$/,''),cfg.key.trim(),{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});return cloudClient;}
function cloudForm(){const cfg=getCloudConfig()||{};modal('Private Cloud einrichten',`<div class="notice"><strong>Einmalige Einrichtung erforderlich:</strong> Erstelle zuerst ein Supabase-Projekt und führe die SQL-Datei aus dem ZIP im SQL Editor aus. Trage dann nur deine Projekt-URL und den <em>Publishable/anon Key</em> ein – niemals den geheimen service_role-Key.</div><form data-form="cloud-config"><div class="field"><label>Supabase-Projekt-URL</label><input type="url" name="url" value="${esc(cfg.url||'')}" placeholder="https://deinprojekt.supabase.co" required></div><div class="field"><label>Publishable / anon Key (öffentlich)</label><input name="key" value="${esc(cfg.key||'')}" placeholder="sb_publishable_…" required></div>${footer('Zugang speichern')}</form>${cfg.url?`<div class="separator"></div>${cloudUser?`<div class="notice">Angemeldet: ${esc(cloudUser.email||'')}</div><div class="toolbar"><button class="ghost" data-action="cloud-check">Jetzt synchronisieren</button><button class="danger-btn" data-action="cloud-logout">Abmelden</button></div>`:`<form data-form="cloud-auth"><div class="field"><label>E-Mail</label><input type="email" name="email" required autocomplete="email"></div><div class="field"><label>Passwort (mindestens 6 Zeichen)</label><input type="password" name="password" required minlength="6" autocomplete="current-password"></div><div class="stack"><button class="button" type="submit" name="mode" value="login">Anmelden</button><button class="ghost" type="submit" name="mode" value="signup">Neues Cloud-Konto erstellen</button></div><p class="hint">Nach einer Registrierung kann eine Bestätigung per E-Mail nötig sein. Öffne dann die App erneut und melde dich an.</p></form>`}`:''}`);}
async function connectCloud(silent=true){if(cloudBusy)return;cloudBusy=true;try{await initCloudClient();const {data:auth,error}=await cloudClient.auth.getSession();if(error)throw error;cloudUser=auth.session?.user||null;if(cloudUser)await syncCloud(true);else {cloudStatus='local';syncMessage='Cloud konfiguriert, bitte anmelden';}}catch(e){cloudStatus='error';syncMessage=e.message||String(e);if(!silent)alert('Cloud-Verbindung: '+syncMessage);}finally{cloudBusy=false;render();}}
async function cloudAuth(fd,mode){if(!cloudClient){try{await initCloudClient()}catch(e){alert(e.message);return;}}const email=String(fd.get('email')||'').trim(),password=String(fd.get('password')||'');try{const auth=mode==='signup'?await cloudClient.auth.signUp({email,password}):await cloudClient.auth.signInWithPassword({email,password});if(auth.error)throw auth.error;if(!auth.data.session){alert('Registrierung durchgeführt. Bitte bestätige gegebenenfalls deine E-Mail und melde dich danach an.');return;}cloudUser=auth.data.user;cloudStatus='connected';closeModal();await syncCloud(true);render();}catch(e){alert('Anmeldung fehlgeschlagen: '+e.message);}}
async function cloudUpload(){if(!cloudClient||!cloudUser)return;const {error}=await cloudClient.from('stammtisch_documents').upsert({owner_id:cloudUser.id,content:data,updated_at:new Date().toISOString()},{onConflict:'owner_id'});if(error)throw error;localStorage.setItem(BASELINE_KEY,data.modifiedAt);cloudStatus='connected';syncMessage='Synchronisiert am '+new Date().toLocaleString('de-AT');}
function adoptCloud(d){data=assertData(structuredClone(d));localStorage.setItem(DATA_KEY,JSON.stringify(data));localStorage.setItem(BASELINE_KEY,data.modifiedAt);cloudStatus='connected';syncMessage='Cloud-Daten übernommen';render();}
const hasData=d=>!!(d.members.length||d.meetings.length||d.fines.length||d.payments.length);
async function syncCloud(fromConnect=false){if(!cloudClient||!cloudUser||!navigator.onLine){if(!navigator.onLine){syncMessage='Offline – Änderungen bleiben lokal gespeichert';render();}return;}try{const {data:record,error}=await cloudClient.from('stammtisch_documents').select('content').eq('owner_id',cloudUser.id).maybeSingle();if(error)throw error;const remote=record?.content;if(!remote){await cloudUpload();render();return;}assertData(remote);const baseline=localStorage.getItem(BASELINE_KEY);if(!baseline){if(!hasData(data)){adoptCloud(remote);return;}if(!hasData(remote)){await cloudUpload();render();return;}if(data.modifiedAt===remote.modifiedAt){localStorage.setItem(BASELINE_KEY,data.modifiedAt);cloudStatus='connected';render();return;}pendingRemote=remote;conflictModal('Auf diesem iPhone und in der Cloud liegen Daten. Welche Version möchtest du behalten?');return;}const localChanged=data.modifiedAt!==baseline,remoteChanged=remote.modifiedAt!==baseline;
 if(remoteChanged&&localChanged&&remote.modifiedAt!==data.modifiedAt){pendingRemote=remote;conflictModal('Die Daten wurden auf zwei Geräten geändert. Bitte wähle bewusst, welche Version bleiben soll.');return;}if(remoteChanged&&!localChanged){adoptCloud(remote);return;}if(localChanged&&!remoteChanged){await cloudUpload();render();return;}cloudStatus='connected';syncMessage='Alle Änderungen synchronisiert';render();}catch(e){cloudStatus='error';syncMessage=e.message||String(e);render();if(!fromConnect)alert('Cloud-Sync fehlgeschlagen: '+syncMessage);}}
function conflictModal(info){modal('Cloud-Daten auswählen',`<div class="notice warning">${esc(info)} Eine Auswahl ersetzt die andere Version. Vorher am besten ein JSON-Backup exportieren.</div><div class="stack" style="margin-top:16px"><button class="ghost" data-action="export-json">↓ Erst ein JSON-Backup herunterladen</button><button class="button" data-action="cloud-download">Cloud-Daten auf dieses iPhone laden</button><button class="danger-btn" data-action="cloud-upload">Lokale Daten in die Cloud hochladen</button></div>`);}
function queueSync(){if(!cloudUser)return;clearTimeout(syncTimer);syncTimer=setTimeout(()=>syncCloud(),1200);}

/* Interaktionen */
document.addEventListener('click',async ev=>{const el=ev.target.closest('[data-action],[data-page]');if(!el)return;
 const action=el.dataset.action,id=el.dataset.id;if(el.dataset.page){page=el.dataset.page;render();window.scrollTo({top:0,behavior:'instant'});return;}
 switch(action){case'close':closeModal();break;case'member-new':memberForm();break;case'member-edit':memberForm(id);break;case'bulk-2026':bulk2026Form();break;case'meeting-new':if(!data.members.filter(m=>m.active!==false).length){alert('Bitte zuerst ein aktives Mitglied anlegen.');memberForm();}else meetingForm();break;case'meeting-edit':meetingForm(id);break;case'attend':attStatus(id,el.dataset.status);break;case'fine-new':fineForm();break;case'fine-pay':payForm(id);break;case'fine-view':fineView(id);break;case'rank-year':rankYear=el.dataset.year;render();break;case'export-csv':exportCSV(el.dataset.kind);break;case'export-json':exportJSON();break;
 case'meeting-delete':{const m=data.meetings.find(x=>x.id===id),linked=data.fines.filter(f=>f.meetingId===id);if(!m)break;if(linked.some(f=>finePaid(f.id)>0))return alert('Treffen mit bereits bezahlten Strafen kann nicht gelöscht werden.');if(confirm('Dieses Treffen und seine unbezahlten Abwesenheitsstrafen endgültig löschen?')){data.meetings=data.meetings.filter(x=>x.id!==id);data.fines=data.fines.filter(f=>f.meetingId!==id);closeModal();persist();}break;}
 case'payment-delete':{const p=data.payments.find(x=>x.id===id);if(p&&confirm('Diese Zahlung stornieren? Der Betrag wird wieder offen.')){const fid=p.fineId;data.payments=data.payments.filter(x=>x.id!==id);closeModal();persist();fineView(fid);}break;}
 case'fine-delete':{const f=data.fines.find(x=>x.id===id);if(f&&!finePaid(f.id)&&confirm('Diese noch unbezahlte Strafe löschen?')){data.fines=data.fines.filter(x=>x.id!==id);closeModal();persist();}break;}
 case'cloud-setup':cloudForm();break;case'cloud-check':closeModal();await syncCloud();break;case'cloud-download':if(pendingRemote&&confirm('Lokale Daten durch die Cloud-Version ersetzen?')){adoptCloud(pendingRemote);pendingRemote=null;closeModal();}break;
 case'cloud-upload':if(confirm('Cloud-Daten durch die lokale Version ersetzen?')){try{await cloudUpload();pendingRemote=null;closeModal();render();}catch(e){alert('Cloud-Upload fehlgeschlagen: '+e.message)}}break;
 case'cloud-logout':if(cloudClient&&confirm('Von der Cloud abmelden? Lokale Daten bleiben auf diesem iPhone.')){await cloudClient.auth.signOut();cloudUser=null;cloudStatus='local';syncMessage='Cloud abgemeldet';closeModal();render();}break;
 }
});
$('#dialog').addEventListener('submit',async ev=>{ev.preventDefault();const form=ev.target,fd=new FormData(form);switch(form.dataset.form){case'member':saveMember(fd);break;case'bulk-2026':saveBulk2026(fd);break;case'meeting':saveMeeting(fd);break;case'fine':saveFine(fd);break;case'payment':savePayment(fd);break;case'cloud-config':{const cfg={url:String(fd.get('url')||'').trim().replace(/\/$/,''),key:String(fd.get('key')||'').trim()};if(!/^https:\/\/[a-z0-9-]+\.supabase\.co$/i.test(cfg.url))return alert('Bitte eine gültige https://…supabase.co Projekt-URL eingeben.');if(cfg.key.length<20)return alert('Bitte einen gültigen Publishable / anon Key eingeben.');const old=getCloudConfig();if(old?.url!==cfg.url||old?.key!==cfg.key){localStorage.removeItem(BASELINE_KEY);cloudClient=null;cloudUser=null;}localStorage.setItem(CLOUD_KEY,JSON.stringify(cfg));closeModal();await connectCloud(false);cloudForm();break;}case'cloud-auth':{const submitter=ev.submitter;await cloudAuth(fd,submitter?.value||'login');break;}}});
document.addEventListener('change',async e=>{const t=e.target;if(t?.name==='organizerId'&&t.matches('[data-organizer-auto]')){t.dataset.organizerAuto='off';return;}if(t?.name==='date'&&t.closest('form[data-form="meeting"]')){const form=t.closest('form');const chooser=form.querySelector('[name="organizerId"]');if(chooser?.dataset.organizerAuto==='on'){const meetingId=form.querySelector('[name="id"]')?.value||'';chooser.value=suggestedOrganizer(t.value,meetingId)?.id||'';}return;}if(t?.id!=='backupFile')return;const file=e.target.files?.[0];if(!file)return;try{const obj=assertData(JSON.parse(await file.text()));if(!confirm('Alle aktuellen Daten durch dieses Backup ersetzen? Vorher am besten selbst ein Backup herunterladen.'))return;data=obj;localStorage.setItem(DATA_KEY,JSON.stringify(data));localStorage.removeItem(BASELINE_KEY);render();if(cloudUser)await syncCloud();alert('Backup wiederhergestellt.');}catch(err){alert('Import nicht möglich: '+err.message)}});
window.addEventListener('online',()=>{if(cloudUser)syncCloud()});
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&cloudUser)syncCloud()});
render();if(getCloudConfig())connectCloud();
if('serviceWorker'in navigator && window.isSecureContext){navigator.serviceWorker.register('./service-worker.js').catch(console.warn);}
